//! Traits that let the triangulator accept user-supplied point and index types,
//! mirroring `mapbox::util::nth` and the `N` template parameter of the C++ API.

/// A 2D point. Implemented for the common tuple / array / slice shapes so that
/// a polygon can be handed over without copying it into a bespoke type first.
pub trait Point {
    fn x(&self) -> f64;
    fn y(&self) -> f64;
}

impl Point for [f64; 2] {
    fn x(&self) -> f64 {
        self[0]
    }
    fn y(&self) -> f64 {
        self[1]
    }
}

impl Point for [f32; 2] {
    fn x(&self) -> f64 {
        self[0] as f64
    }
    fn y(&self) -> f64 {
        self[1] as f64
    }
}

impl Point for (f64, f64) {
    fn x(&self) -> f64 {
        self.0
    }
    fn y(&self) -> f64 {
        self.1
    }
}

impl<P: Point> Point for &P {
    fn x(&self) -> f64 {
        (*self).x()
    }
    fn y(&self) -> f64 {
        (*self).y()
    }
}

/// Integer type used for the emitted triangle indices. `from_index` performs the
/// same truncating conversion as `static_cast<N>` does in the C++ original.
pub trait IndexType: Copy {
    fn from_index(i: usize) -> Self;
}

macro_rules! impl_index_type {
    ($($t:ty),*) => {
        $(
            impl IndexType for $t {
                fn from_index(i: usize) -> Self {
                    i as $t
                }
            }
        )*
    };
}

impl_index_type!(u16, u32, u64, usize, i16, i32, i64);

