//! Coordinate-only geometric predicates. Keeping them free of node/arena access
//! means the arithmetic can be read (and compared against the C++ source) on its
//! own, and the caller never has to juggle two borrows of the node arena.

/// Signed area of the triangle `p q r`, doubled. Negative for a clockwise turn
/// in the winding earcut works in.
pub fn area(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// Whether `p` lies inside (or on the boundary of) the triangle `a b c`.
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// `(0 < val) - (val < 0)`
pub fn sign(val: f64) -> i32 {
    i32::from(0.0 < val) - i32::from(val < 0.0)
}

/// For collinear points `p`, `q`, `r`: whether `q` lies on the segment `p r`.
pub fn on_segment(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> bool {
    qx <= px.max(rx) && qx >= px.min(rx) && qy <= py.max(ry) && qy >= py.min(ry)
}

/// Interleave the low 15 bits of the two coordinates into a z-order (Morton) key.
pub fn z_order(x_: f64, y_: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
    // coords are transformed into non-negative 15-bit integer range
    let mut x = ((x_ - min_x) * inv_size) as i32;
    let mut y = ((y_ - min_y) * inv_size) as i32;

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x3333_3333;
    x = (x | (x << 1)) & 0x5555_5555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x3333_3333;
    y = (y | (y << 1)) & 0x5555_5555;

    x | (y << 1)
}

