//! The doubly linked ring node and its arena.
//!
//! The C++ original threads raw `Node*` pointers through the algorithm and hands
//! out storage from a bump allocator. Here nodes live in a `Vec` and links are
//! `usize` slots into it, with `NULL` standing in for a null pointer.

/// Sentinel used where the C++ code would hold `nullptr`.
pub const NULL: usize = usize::MAX;

pub struct Node {
    /// Index of this vertex in the flattened input coordinate list.
    pub i: usize,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in a polygon ring.
    pub prev: usize,
    pub next: usize,

    /// z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: usize, x: f64, y: f64) -> Self {
        Node {
            i,
            x,
            y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        }
    }
}

/// Bump-allocated node storage; slots are never freed while a triangulation runs
/// because removed nodes are still reachable through the z-order links.
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Self {
        Arena { nodes: Vec::new() }
    }

    /// Drop every node and pre-size the storage for `n` upcoming nodes.
    pub fn reset(&mut self, n: usize) {
        self.nodes.clear();
        self.nodes.reserve(n);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
        self.nodes.shrink_to_fit();
    }

    pub fn construct(&mut self, i: usize, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }
}

impl std::ops::Index<usize> for Arena {
    type Output = Node;

    fn index(&self, i: usize) -> &Node {
        &self.nodes[i]
    }
}

impl std::ops::IndexMut<usize> for Arena {
    fn index_mut(&mut self, i: usize) -> &mut Node {
        &mut self.nodes[i]
    }
}

