//! Ear-clipping triangulation of a polygon with holes.
//!
//! Direct port of the C++ `mapbox::earcut` control flow: rings become circular
//! doubly linked lists, holes are stitched into the outer ring with bridges, then
//! ears are clipped one by one with three escalating fallback passes. For inputs
//! above a size threshold the vertices are additionally indexed along a z-order
//! curve so the "is this triangle empty" test can be done locally.

use super::geometry::{area, on_segment, point_in_triangle, sign, z_order};
use super::node::{Arena, NULL};
use super::point::{IndexType, Point, Ring};

pub struct Earcut<N: IndexType> {
    /// Flat triangle list; three entries per triangle.
    pub indices: Vec<N>,
    /// Number of input vertices consumed so far, used to number the rings.
    vertices: usize,

    nodes: Arena,

    hashing: bool,
    min_x: f64,
    min_y: f64,
    max_x: f64,
    max_y: f64,
    inv_size: f64,
}

impl<N: IndexType> Default for Earcut<N> {
    fn default() -> Self {
        Self::new()
    }
}

impl<N: IndexType> Earcut<N> {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Arena::new(),
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Triangulate `polygon`: ring 0 is the outer contour, the rest are holes.
    pub fn run<R: Ring>(&mut self, polygon: &[R]) {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if polygon.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < polygon.len() {
            threshold -= polygon[i].points().len() as i32;
            len += polygon[i].points().len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reset(len * 3 / 2);
        self.indices.reserve(len + polygon[0].points().len());

        let mut outer_node = self.linked_list(polygon[0].points(), true);
        if outer_node == NULL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if polygon.len() > 1 {
            outer_node = self.eliminate_holes(polygon, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                self.max_x = self.max_x.max(x);
                self.max_y = self.max_y.max(y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // minX, minY and inv_size are later used to transform coords
            // into integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Create a circular doubly linked list from polygon points in the specified
    /// winding order.
    fn linked_list<P: Point>(&mut self, points: &[P], clockwise: bool) -> usize {
        let mut sum = 0.0;
        let len = points.len();
        let mut last = NULL;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            sum += (p2.x() - p1.x()) * (p1.y() + p2.y());
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i].x(), points[i].y(), last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i].x(), points[i].y(), last);
            }
        }

        if last != NULL && self.equals(last, self.nodes[last].next) {
            let next = self.nodes[last].next;
            self.remove_node(last);
            last = next;
        }

        self.vertices += len;

        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NULL {
            return start;
        }
        let mut end = if end == NULL { start } else { end };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;
            if !self.nodes[p].steiner
                && (self.equals(p, next) || self.area(prev, p, next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear_start: usize, pass: i32) {
        let mut ear = ear_start;
        if ear == NULL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let sliceable = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if sliceable {
                // cut off the triangle
                self.indices.push(N::from_index(self.nodes[prev].i));
                self.indices.push(N::from_index(self.nodes[ear].i));
                self.indices.push(N::from_index(self.nodes[next].i));

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, NULL);
                    self.earcut_linked(filtered, 1);
                }
                // if this didn't work, try curing all small self-intersections locally
                else if pass == 1 {
                    let filtered = self.filter_points(ear, NULL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                }
                // as a last resort, try splitting the remaining polygon into two
                else if pass == 2 {
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[c].next;

        while p != a {
            if self.point_in_triangle(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    /// Same as [`Earcut::is_ear`], but only visits candidate points whose z-order
    /// key falls inside the triangle's bounding box range.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = self.nodes[a].x.min(self.nodes[b].x.min(self.nodes[c].x));
        let min_ty = self.nodes[a].y.min(self.nodes[b].y.min(self.nodes[c].y));
        let max_tx = self.nodes[a].x.max(self.nodes[b].x.max(self.nodes[c].x));
        let max_ty = self.nodes[a].y.max(self.nodes[b].y.max(self.nodes[c].y));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        let mut n = self.nodes[ear].prev_z;

        while p != NULL && self.nodes[p].z <= max_z && n != NULL && self.nodes[n].z >= min_z {
            if self.in_box(p, min_tx, min_ty, max_tx, max_ty)
                && p != a
                && p != c
                && self.point_in_triangle(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;

            if self.in_box(n, min_tx, min_ty, max_tx, max_ty)
                && n != a
                && n != c
                && self.point_in_triangle(a, b, c, n)
                && self.area(self.nodes[n].prev, n, self.nodes[n].next) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].prev_z;
        }

        // look for remaining points in decreasing z-order
        while n != NULL && self.nodes[n].z >= min_z {
            if self.in_box(n, min_tx, min_ty, max_tx, max_ty)
                && n != a
                && n != c
                && self.point_in_triangle(a, b, c, n)
                && self.area(self.nodes[n].prev, n, self.nodes[n].next) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].prev_z;
        }

        // look for remaining points in increasing z-order
        while p != NULL && self.nodes[p].z <= max_z {
            if self.in_box(p, min_tx, min_ty, max_tx, max_ty)
                && p != a
                && p != c
                && self.point_in_triangle(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start_node: usize) -> usize {
        let mut start = start_node;
        if start == NULL {
            return start;
        }

        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(N::from_index(self.nodes[a].i));
                self.indices.push(N::from_index(self.nodes[p].i));
                self.indices.push(N::from_index(self.nodes[b].i));

                // remove two nodes involved
                self.remove_node(p);
                self.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NULL)
    }

    /// Try splitting a polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a2 = self.filter_points(a, a_next);
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, c_next);

                    // run earcut on each half
                    self.earcut_linked(a2, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon.
    fn eliminate_holes<R: Ring>(&mut self, polygon: &[R], outer: usize) -> usize {
        let mut outer_node = outer;

        let mut queue: Vec<usize> = Vec::new();
        for ring in polygon.iter().skip(1) {
            let list = self.linked_list(ring.points(), false);
            if list != NULL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        // `std::sort` with a strict `x <` comparator; a stable sort agrees with it
        // for the small inputs libstdc++ resolves by insertion sort.
        queue.sort_by(|&a, &b| {
            if self.nodes[a].x < self.nodes[b].x {
                std::cmp::Ordering::Less
            } else if self.nodes[b].x < self.nodes[a].x {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        });

        // process holes from left to right
        for i in 0..queue.len() {
            outer_node = self.eliminate_hole(queue[i], outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring,
    /// and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NULL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, br_next);
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, b_next)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and an outer ring.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NULL;

        // find a segment intersected by a ray from the hole's leftmost vertex to
        // the left; the segment's endpoint with lesser x will be the potential
        // connection vertex
        loop {
            let pn = self.nodes[p].next;
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            let nx = self.nodes[pn].x;
            let ny = self.nodes[pn].y;

            if hy <= py && hy >= ny && ny != py {
                let x = px + (hy - py) * (nx - px) / (ny - py);
                if x <= hx && x > qx {
                    qx = x;
                    m = if px < nx { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }

            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NULL {
            return NULL;
        }

        // look for points inside the triangle of hole vertex, segment intersection
        // and endpoint; if there are no points found, we have a valid connection;
        // otherwise choose the vertex of the polygon with the least x
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = m;
        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;

            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    /// Whether the sector in vertex `m` contains the sector in vertex `p` in the
    /// same coordinates.
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    /// Interlink polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
            self.nodes[p].prev_z = prev;
            self.nodes[p].next_z = next;
            p = next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm, ordering by z-order key.
    fn sort_linked(&mut self, head: usize) -> usize {
        let mut list = head;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        leftmost
    }

    /// Check if a diagonal between two polygon nodes is valid (lies in the polygon
    /// interior).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        let b_next = self.nodes[b].next;

        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                // does not create opposite-facing sectors
                && (self.area(a_prev, a, b_prev) != 0.0 || self.area(a, b_prev, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(a_prev, a, a_next) > 0.0
                    && self.area(b_prev, b, b_next) > 0.0))
    }

    /// Check if two segments intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // p1, q1 and p2 are collinear and p2 lies on p1q1
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are collinear and q2 lies on p1q1
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are collinear and p1 lies on p2q2
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are collinear and q1 lies on p2q2
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if self.area(a_prev, a, a_next) < 0.0 {
            self.area(a, b, a_next) >= 0.0 && self.area(a, a_prev, b) >= 0.0
        } else {
            self.area(a, b, a_prev) < 0.0 || self.area(a, a_next, b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px_mid = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py_mid = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (nx, ny) = (self.nodes[pn].x, self.nodes[pn].y);
            if ((py > py_mid) != (ny > py_mid))
                && ny != py
                && (px_mid < (nx - px) * (py_mid - py) / (ny - py) + px)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        inside
    }

    /// Link two polygon vertices with a bridge.
    ///
    /// If the vertices belong to the same ring it splits the polygon into two; if
    /// one belongs to the outer ring and another to a hole, it merges them into a
    /// single ring.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.nodes.construct(ai, ax, ay);
        let b2 = self.nodes.construct(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with the previous one (in a circular
    /// doubly linked list).
    fn insert_node(&mut self, i: usize, x: f64, y: f64, last: usize) -> usize {
        let p = self.nodes.construct(i, x, y);

        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }

        p
    }

    fn remove_node(&mut self, p: usize) {
        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if prev_z != NULL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NULL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    // --- node-level wrappers around the coordinate predicates ---

    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        area(
            self.nodes[p].x,
            self.nodes[p].y,
            self.nodes[q].x,
            self.nodes[q].y,
            self.nodes[r].x,
            self.nodes[r].y,
        )
    }

    /// Check if two points are equal.
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    fn point_in_triangle(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
        point_in_triangle(
            self.nodes[a].x,
            self.nodes[a].y,
            self.nodes[b].x,
            self.nodes[b].y,
            self.nodes[c].x,
            self.nodes[c].y,
            self.nodes[p].x,
            self.nodes[p].y,
        )
    }

    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        on_segment(
            self.nodes[p].x,
            self.nodes[p].y,
            self.nodes[q].x,
            self.nodes[q].y,
            self.nodes[r].x,
            self.nodes[r].y,
        )
    }

    fn in_box(&self, p: usize, min_tx: f64, min_ty: f64, max_tx: f64, max_ty: f64) -> bool {
        self.nodes[p].x >= min_tx
            && self.nodes[p].x <= max_tx
            && self.nodes[p].y >= min_ty
            && self.nodes[p].y <= max_ty
    }

    fn z_order(&self, x: f64, y: f64) -> i32 {
        z_order(x, y, self.min_x, self.min_y, self.inv_size)
    }
}

