//! Small shims for the C library functions the original program relies on.

/// `std::atoi`, matching glibc's `(int) strtol(nptr, NULL, 10)`: leading
/// whitespace and an optional sign are accepted, parsing stops at the first
/// non-digit, an unparsable string yields 0, and out-of-range values saturate at
/// the `long` limits before being truncated to `int`.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut acc: i64 = 0;
    let mut overflow = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !overflow {
            let digit = i64::from(bytes[i] - b'0');
            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => acc = v,
                None => overflow = true,
            }
        }
        i += 1;
    }

    let value: i64 = if overflow {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    value as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn parses_like_the_c_library() {
        assert_eq!(atoi("2"), 2);
        assert_eq!(atoi("  12"), 12);
        assert_eq!(atoi("-5"), -5);
        assert_eq!(atoi("+7"), 7);
        assert_eq!(atoi("4.9"), 4);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi(""), 0);
        assert_eq!(atoi("99999999999999"), 276676607);
        // saturates at LONG_MAX, then truncates to int
        assert_eq!(atoi("999999999999999999999999"), -1);
    }
}

