// Port of tests/test2.cpp: triangulate an n-by-n square, with a centred square
// hole once n > 1, and print the resulting triangle indices.

mod cstdlib;
mod earcut;

use std::io::Write;

use cstdlib::atoi;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 2;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let n = f64::from(n);
    let outer: Vec<[f64; 2]> = vec![[0.0, 0.0], [n, 0.0], [n, n], [0.0, n]];
    polygon.push(outer);

    if n > 1.0 {
        let hole: Vec<[f64; 2]> = vec![
            [0.25 * n, 0.25 * n],
            [0.75 * n, 0.25 * n],
            [0.75 * n, 0.75 * n],
            [0.25 * n, 0.75 * n],
        ];
        polygon.push(hole);
    }

    let indices: Vec<u32> = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for idx in &indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

