//! Correctness checks for the triangulator itself.
//!
//! Byte-exact agreement with the C++ binary on the two shapes `test2` builds is
//! necessary but not sufficient — those never exceed 80 vertices, so they never
//! exercise the z-order hashing path. These tests use earcut's own "deviation"
//! metric (triangulated area vs. polygon area) on larger inputs to cover it.

use super::earcut;

/// Absolute area of a ring.
fn ring_area(ring: &[[f64; 2]]) -> f64 {
    let len = ring.len();
    let mut sum = 0.0;
    let mut j = if len > 0 { len - 1 } else { 0 };
    for i in 0..len {
        sum += (ring[j][0] - ring[i][0]) * (ring[i][1] + ring[j][1]);
        j = i;
    }
    (sum / 2.0).abs()
}

/// Relative difference between the total area of the triangles and the area of the
/// polygon; 0 for a perfect triangulation.
fn deviation(polygon: &[Vec<[f64; 2]>], indices: &[u32]) -> f64 {
    let flat: Vec<[f64; 2]> = polygon.iter().flatten().copied().collect();

    let mut polygon_area = ring_area(&polygon[0]);
    for hole in polygon.iter().skip(1) {
        polygon_area -= ring_area(hole);
    }

    let mut triangles_area = 0.0;
    for t in indices.chunks(3) {
        let a = flat[t[0] as usize];
        let b = flat[t[1] as usize];
        let c = flat[t[2] as usize];
        triangles_area +=
            ((a[0] - c[0]) * (b[1] - a[1]) - (a[0] - b[0]) * (c[1] - a[1])).abs() / 2.0;
    }

    if polygon_area == 0.0 && triangles_area == 0.0 {
        0.0
    } else {
        ((triangles_area - polygon_area) / polygon_area).abs()
    }
}

fn check(polygon: &[Vec<[f64; 2]>], expected_triangles: usize) {
    let indices: Vec<u32> = earcut(polygon);
    let vertex_count: usize = polygon.iter().map(|r| r.len()).sum();

    assert_eq!(indices.len() % 3, 0, "indices must come in triples");
    assert_eq!(
        indices.len() / 3,
        expected_triangles,
        "unexpected triangle count"
    );
    for &i in &indices {
        assert!((i as usize) < vertex_count, "index {i} out of range");
    }
    let dev = deviation(polygon, &indices);
    assert!(dev < 1e-12, "area deviation too large: {dev}");
}

/// `cos`/`sin` sampled ring, `n` points, radius `r`, centred on `c`.
fn circle(n: usize, r: f64, c: [f64; 2], clockwise: bool) -> Vec<[f64; 2]> {
    (0..n)
        .map(|i| {
            let step = if clockwise { -1.0 } else { 1.0 };
            let a = step * 2.0 * std::f64::consts::PI * (i as f64) / (n as f64);
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        })
        .collect()
}

#[test]
fn matches_reference_square() {
    let polygon = vec![vec![[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]];
    let indices: Vec<u32> = earcut(&polygon);
    assert_eq!(indices, vec![2, 3, 0, 0, 1, 2]);
}

#[test]
fn matches_reference_square_with_hole() {
    let polygon = vec![
        vec![[0.0, 0.0], [2.0, 0.0], [2.0, 2.0], [0.0, 2.0]],
        vec![[0.5, 0.5], [1.5, 0.5], [1.5, 1.5], [0.5, 1.5]],
    ];
    let indices: Vec<u32> = earcut(&polygon);
    assert_eq!(
        indices,
        vec![0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6, 6, 1, 2]
    );
}

#[test]
fn degenerate_input_yields_nothing() {
    let empty: Vec<Vec<[f64; 2]>> = Vec::new();
    assert!(earcut::<u32, _>(&empty).is_empty());

    // all four corners collapsed onto one point
    let collapsed = vec![vec![[0.0; 2], [0.0; 2], [0.0; 2], [0.0; 2]]];
    assert!(earcut::<u32, _>(&collapsed).is_empty());

    // fewer than three distinct vertices
    let sliver = vec![vec![[0.0, 0.0], [1.0, 1.0]]];
    assert!(earcut::<u32, _>(&sliver).is_empty());
}

#[test]
fn convex_ring_below_hashing_threshold() {
    let polygon = vec![circle(40, 10.0, [0.0, 0.0], false)];
    check(&polygon, 38);
}

#[test]
fn large_ring_uses_z_order_hashing() {
    // > 80 vertices, so `hashing` is on and isEarHashed/indexCurve/sortLinked run
    let polygon = vec![circle(500, 10.0, [0.0, 0.0], false)];
    check(&polygon, 498);
}

#[test]
fn large_ring_with_holes_uses_z_order_hashing() {
    let polygon = vec![
        circle(120, 20.0, [0.0, 0.0], false),
        circle(40, 4.0, [-8.0, 0.0], true),
        circle(40, 4.0, [8.0, 3.0], true),
    ];
    // V + 2H - 2 triangles for a polygon with H holes
    check(&polygon, 120 + 80 + 2 * 2 - 2);
}

#[test]
fn concave_comb() {
    let teeth = 30;
    let mut ring = vec![[0.0, 0.0]];
    for i in 0..teeth {
        let x = i as f64;
        ring.push([x + 0.2, 0.0]);
        ring.push([x + 0.2, 3.0]);
        ring.push([x + 0.8, 3.0]);
        ring.push([x + 0.8, 0.0]);
    }
    ring.push([teeth as f64, 0.0]);
    ring.push([teeth as f64, -1.0]);
    ring.push([0.0, -1.0]);
    let n = ring.len();
    check(&vec![ring], n - 2);
}

#[test]
fn colinear_points_are_filtered_out() {
    // the midpoints on each edge are colinear and must not produce triangles
    let polygon = vec![vec![
        [0.0, 0.0],
        [1.0, 0.0],
        [2.0, 0.0],
        [2.0, 1.0],
        [2.0, 2.0],
        [1.0, 2.0],
        [0.0, 2.0],
        [0.0, 1.0],
    ]];
    let indices: Vec<u32> = earcut(&polygon);
    let dev = deviation(&polygon, &indices);
    assert!(dev < 1e-12, "area deviation too large: {dev}");
}

#[test]
fn hole_touching_the_outer_ring() {
    let polygon = vec![
        vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
        // leftmost hole vertex sits exactly on the outer edge x = 0
        vec![[0.0, 2.0], [2.0, 1.0], [2.0, 3.0]],
    ];
    let indices: Vec<u32> = earcut(&polygon);
    let dev = deviation(&polygon, &indices);
    assert!(dev < 1e-12, "area deviation too large: {dev}");
}

#[test]
fn steiner_point_is_preserved() {
    // a single-vertex "hole" is a steiner point: it must appear in the output
    let polygon = vec![
        vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
        vec![[2.0, 2.0]],
    ];
    let indices: Vec<u32> = earcut(&polygon);
    assert!(indices.contains(&4), "steiner point was dropped");
    let dev = deviation(&polygon, &indices);
    assert!(dev < 1e-12, "area deviation too large: {dev}");
}

