//! A dependency-free Rust port of `mapbox/earcut.hpp`.
//!
//! ```ignore
//! let polygon = vec![vec![[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]];
//! let indices: Vec<u32> = earcut::earcut(&polygon);
//! ```

// The port keeps the full public surface of the C++ header (extra point shapes,
// index widths, predicates) even though test2 only exercises part of it.
#![allow(dead_code)]

pub mod geometry;
pub mod node;
pub mod point;
pub mod triangulate;

#[allow(unused_imports)]
pub use point::{IndexType, Point, Ring};
pub use triangulate::Earcut;

/// Triangulate a polygon given as a list of rings (ring 0 is the outer contour,
/// the remaining rings are holes) and return a flat list of triangle indices into
/// the concatenated vertex list.
pub fn earcut<N: IndexType, R: Ring>(polygon: &[R]) -> Vec<N> {
    let mut earcut = Earcut::<N>::new();
    earcut.run(polygon);
    earcut.indices
}

